def declare_winner(db, session_id, seat_id, pot_pts, operator_id):
    session = db_query('SELECT * FROM poker_sessions WHERE id = ?', (session_id,)).fetchone()
    if not session:
        raise SessionNotFound()
    seat = db_query('SELECT * FROM poker_seats WHERE id = ? AND session_id = ?', (seat_id, session_id)).fetchone()
    if not seat or not seat['player_id']:
        raise InvalidSeat('seat_must_have_linked_player')
    if pot_pts <= 0 or pot_pts > 10_000_000:
        raise InvalidAmount()
    rake_option = json.loads(get_system_setting('poker_rake_option', '{"option_id":"no_rake","rake_pct":0,"rake_cap_pts":0}'))
    rake_pts = min(int(pot_pts * rake_option['rake_pct']), rake_option['rake_cap_pts']) if rake_option['rake_pct'] > 0 else 0
    pot_to_winner = pot_pts - rake_pts
    operator_account_id = get_system_setting('poker_rake_operator_account_id')
    with db_transaction(db):
        if rake_pts > 0 and operator_account_id:
            _add_points(db, operator_account_id, rake_pts, label=f'poker_rake_session_{session_id}')
        _add_points(db, seat['player_id'], pot_to_winner, label=f'poker_pot_win_session_{session_id}')
        log_id = db_execute('INSERT INTO poker_hand_log (session_id, hand_number, started_at, ended_at, stage_reached, ended_by, community_cards, seats, winners) VALUES (?, ?, ?, CURRENT_TIMESTAMP, ?, ?, ?, ?, ?)', (session_id, get_next_hand_number(db, session_id), session['created_at'], session['stage'], 'operator_declared', session['community_cards_json'], json.dumps([dict(s) for s in get_session_seats(db, session_id)]), json.dumps([{'seat_id': seat_id, 'player_id': seat['player_id'], 'pot_pts': pot_to_winner, 'rake_pts': rake_pts}]))).lastrowid
    emit_animation_event('A8_POKER_SHOWDOWN', {'winner_seat_id': seat_id})
    return {'declared': True, 'winner_seat_id': seat_id, 'pot_awarded_pts': pot_to_winner, 'rake_pts': rake_pts, 'balance_after_winner': get_balance(db, seat['player_id']), 'hand_log_id': log_id}

