def submit_bet_action(db, session_id, seat_token, action, raise_to_pts=None):
    seat = db_query('SELECT s.*, sess.* FROM poker_seats s JOIN poker_sessions sess ON s.session_id = sess.id WHERE s.join_token = ? AND s.session_id = ?', (seat_token, session_id)).fetchone()
    if not seat:
        raise InvalidToken()
    if seat['folded'] or not seat['active']:
        raise InvalidAction('seat_not_active')
    if seat['id'] != seat['current_bettor_seat_id']:
        raise InvalidAction('not_your_turn')
    pot = json.loads(seat['pot_json'] or '{}')
    main_pot = pot.get('main', 0)
    side_pots = pot.get('side', [])
    current_bet = seat['current_bet_pts']
    seat_round_bet = seat['current_round_bet_pts']
    seat_balance = get_balance(db, seat['player_id'])
    if action == 'fold':
        db_execute('UPDATE poker_seats SET folded = 1, last_action = ? WHERE id = ?', ('fold', seat['id']))
    elif action == 'check':
        if seat_round_bet < current_bet:
            raise InvalidAction('cannot_check_when_bet_pending')
        db_execute('UPDATE poker_seats SET last_action = ? WHERE id = ?', ('check', seat['id']))
    elif action == 'call':
        diff = current_bet - seat_round_bet
        if seat_balance < diff:
            return submit_bet_action(db, session_id, seat_token, 'all_in')
        _atomic_deduct_points(db, seat['player_id'], diff, label=f'poker_call_session_{session_id}')
        main_pot += diff
        db_execute('UPDATE poker_seats SET current_round_bet_pts = ?, total_session_contribution_pts = total_session_contribution_pts + ?, last_action = ? WHERE id = ?', (current_bet, diff, 'call', seat['id']))
    elif action == 'raise':
        if raise_to_pts is None or raise_to_pts < current_bet + seat['min_raise_pts']:
            raise InvalidAction('raise_below_minimum')
        diff = raise_to_pts - seat_round_bet
        if seat_balance < diff:
            return submit_bet_action(db, session_id, seat_token, 'all_in')
        _atomic_deduct_points(db, seat['player_id'], diff, label=f'poker_raise_session_{session_id}')
        main_pot += diff
        new_min_raise = raise_to_pts - current_bet
        db_execute('UPDATE poker_seats SET current_round_bet_pts = ?, total_session_contribution_pts = total_session_contribution_pts + ?, last_action = ? WHERE id = ?', (raise_to_pts, diff, 'raise', seat['id']))
        db_execute('UPDATE poker_sessions SET current_bet_pts = ?, min_raise_pts = ? WHERE id = ?', (raise_to_pts, new_min_raise, session_id))
    elif action == 'all_in':
        all_in_amount = seat_balance
        _atomic_deduct_points(db, seat['player_id'], all_in_amount, label=f'poker_allin_session_{session_id}')
        new_round_bet = seat_round_bet + all_in_amount
        if new_round_bet > current_bet:
            db_execute('UPDATE poker_sessions SET current_bet_pts = ? WHERE id = ?', (new_round_bet, session_id))
        side_pots = compute_side_pots(db, session_id)
        db_execute('UPDATE poker_seats SET current_round_bet_pts = ?, total_session_contribution_pts = total_session_contribution_pts + ?, all_in = 1, last_action = ? WHERE id = ?', (new_round_bet, all_in_amount, 'all_in', seat['id']))
    pot['main'] = main_pot
    pot['side'] = side_pots
    db_execute('UPDATE poker_sessions SET pot_json = ? WHERE id = ?', (json.dumps(pot), session_id))
    next_seat = compute_next_bettor(db, session_id)
    round_complete = next_seat is None
    if not round_complete:
        db_execute('UPDATE poker_sessions SET current_bettor_seat_id = ? WHERE id = ?', (next_seat['id'], session_id))
    return {'action_accepted': True, 'new_pot_pts': main_pot, 'current_bet_pts': read_current_bet(db, session_id), 'next_bettor_seat_id': next_seat['id'] if next_seat else None, 'round_complete': round_complete, 'balance_after': get_balance(db, seat['player_id'])}

def compute_side_pots(db, session_id):
    seats = db_query('SELECT id, total_session_contribution_pts, all_in, folded FROM poker_seats WHERE session_id = ? ORDER BY total_session_contribution_pts ASC', (session_id,)).fetchall()
    side_pots = []
    prior_threshold = 0
    eligible_for_main = [s['id'] for s in seats if not s['folded']]
    for s in seats:
        if s['all_in'] and s['total_session_contribution_pts'] > prior_threshold:
            level = s['total_session_contribution_pts'] - prior_threshold
            pot_pts = level * len(eligible_for_main)
            side_pots.append({'eligible_seat_ids': list(eligible_for_main), 'pot_pts': pot_pts})
            prior_threshold = s['total_session_contribution_pts']
            eligible_for_main = [e for e in eligible_for_main if e != s['id']]
    return side_pots

def compute_next_bettor(db, session_id):
    sess = db_query('SELECT * FROM poker_sessions WHERE id = ?', (session_id,)).fetchone()
    seats = db_query('SELECT * FROM poker_seats WHERE session_id = ? AND active = 1 AND folded = 0 ORDER BY seat_number', (session_id,)).fetchall()
    if len(seats) <= 1:
        return None
    current_seat = next((s for s in seats if s['id'] == sess['current_bettor_seat_id']), None)
    if not current_seat:
        return seats[0]
    current_idx = seats.index(current_seat)
    target_bet = sess['current_bet_pts']
    for offset in range(1, len(seats) + 1):
        candidate = seats[(current_idx + offset) % len(seats)]
        if candidate['all_in']:
            continue
        if candidate['current_round_bet_pts'] < target_bet:
            return candidate
        if offset == len(seats):
            return None
    return None

