function PresetEditor(sessionId, seatList, currentPresets) {
  const palette = generateAllCards();
  const assignments = currentPresets || {};
  const community = [];
  function onDragStart(card) {
    return JSON.stringify(card);
  }
  function onDrop(targetType, targetId, dataTransfer) {
    const card = JSON.parse(dataTransfer);
    if (isCardUsed(card, assignments, community)) {
      showWarning('Sama kortti useassa paikassa');
      return;
    }
    if (targetType === 'seat') {
      assignments[targetId] = assignments[targetId] || [];
      if (assignments[targetId].length >= 2) {
        assignments[targetId].pop();
      }
      assignments[targetId].push(card);
    } else if (targetType === 'community') {
      if (community.length >= 5) {
        community.shift();
      }
      community.push(card);
    }
    updatePreview();
  }
  function updatePreview() {
    for (const [seatId, holes] of Object.entries(assignments)) {
      if (holes.length === 2) {
        fetchEvaluatePreview(holes, community).then(result => {
          renderRankBadge(seatId, result.rank_fi);
        });
      }
    }
  }
  function isCardUsed(card, assignments, community) {
    const allUsed = [...community, ...Object.values(assignments).flat()];
    return allUsed.some(c => c.rank === card.rank && c.suit === card.suit);
  }
  function save() {
    if (!validateAll()) return;
    fetch(`/api/poker/${sessionId}/preset`, { method: 'POST', body: JSON.stringify({preset_hands_json: assignments, community_preview: community}) });
  }
  return {onDragStart, onDrop, save};
}

function validateAll() {
  const allCards = [...community, ...Object.values(assignments).flat()];
  const fingerprints = allCards.map(c => `${c.rank}_${c.suit}`);
  if (new Set(fingerprints).size !== fingerprints.length) {
    return false;
  }
  for (const holes of Object.values(assignments)) {
    if (holes.length !== 0 && holes.length !== 2) {
      return false;
    }
  }
  if (![0, 3, 4, 5].includes(community.length)) {
    return false;
  }
  return true;
}

