class HandReplay {
  constructor(handLogId, canvasCtx) {
    this.handLogId = handLogId;
    this.canvasCtx = canvasCtx;
    this.timeline = [];
    this.currentMs = 0;
    this.totalMs = 0;
    this.playing = false;
    this.lastFrameTs = null;
  }
  async load() {
    const res = await fetch(`/api/poker/hands/${this.handLogId}`);
    this.handData = await res.json();
    this.timeline = this.buildTimelineFromData(this.handData);
    this.totalMs = this.timeline[this.timeline.length - 1].t_ms;
  }
  buildTimelineFromData(data) {
    const seats = JSON.parse(data.seats);
    const community = JSON.parse(data.community_cards || '[]');
    const winners = JSON.parse(data.winners || '[]');
    return [
      {t_ms: 200,  type: 'deal_holes', seats},
      {t_ms: 1700, type: 'community_flop', cards: community.slice(0, 3)},
      {t_ms: 3500, type: 'community_turn', card: community[3]},
      {t_ms: 4500, type: 'community_river', card: community[4]},
      {t_ms: 5500, type: 'reveal_holes', seats},
      {t_ms: 6500, type: 'showdown', winners}
    ];
  }
  play() {
    this.playing = true;
    this.lastFrameTs = performance.now();
    requestAnimationFrame(this.tick.bind(this));
  }
  pause() { this.playing = false; }
  step(deltaMs) {
    this.currentMs = Math.max(0, Math.min(this.totalMs, this.currentMs + deltaMs));
    this.renderAt(this.currentMs);
  }
  tick(now) {
    if (!this.playing) return;
    const dt = now - this.lastFrameTs;
    this.lastFrameTs = now;
    this.currentMs = Math.min(this.currentMs + dt, this.totalMs);
    this.renderAt(this.currentMs);
    if (this.currentMs >= this.totalMs) { this.playing = false; return; }
    requestAnimationFrame(this.tick.bind(this));
  }
  renderAt(t_ms) {
    const passed = this.timeline.filter(e => e.t_ms <= t_ms);
    this.canvasCtx.clearRect(0, 0, 1080, 1920);
    for (const event of passed) {
      this.dispatchAnimation(event, t_ms - event.t_ms);
    }
  }
  dispatchAnimation(event, elapsedSinceEvent) {
    switch (event.type) {
      case 'deal_holes': renderDealHoles(this.canvasCtx, event.seats, elapsedSinceEvent, 60); break;
      case 'community_flop': renderCommunityFlop(this.canvasCtx, event.cards, elapsedSinceEvent); break;
      case 'community_turn':
      case 'community_river': renderCommunitySingle(this.canvasCtx, event.card, elapsedSinceEvent); break;
      case 'reveal_holes': renderHoleReveal(this.canvasCtx, event.seats, elapsedSinceEvent); break;
      case 'showdown': renderShowdown(this.canvasCtx, event.winners, elapsedSinceEvent); break;
    }
  }
}

