class CardRenderer {
  constructor(ctx) {
    this.ctx = ctx;
    this.cardW = 120;
    this.cardH = 168;
    this.spriteCache = new Map();
    this.backPattern = null;
    this.PIP_LAYOUT = PIP_LAYOUT_TABLE;
    this.SUIT_COLORS = {'♠': '#0A0A0A', '♥': '#CC2200', '♦': '#CC2200', '♣': '#0A0A0A'};
    this.SUIT_PATHS = {'♠': SUIT_SVG_PATHS.spade, '♥': SUIT_SVG_PATHS.heart, '♦': SUIT_SVG_PATHS.diamond, '♣': SUIT_SVG_PATHS.club};
  }

  _cacheKey(card, faceUp) {
    if (!faceUp) return 'BACK';
    return `${card.rank}_${card.suit}`;
  }

  _renderCardToOffscreen(card, faceUp) {
    const off = new OffscreenCanvas(this.cardW, this.cardH);
    const octx = off.getContext('2d');
    if (faceUp) {
      octx.fillStyle = '#FBF8EE';
      octx.fillRect(0, 0, this.cardW, this.cardH);
      octx.strokeStyle = '#0A0A0A';
      octx.lineWidth = 1.5;
      octx.strokeRect(0.75, 0.75, this.cardW - 1.5, this.cardH - 1.5);
      this._drawCornerIndex(octx, card, 8, 16, 'top-left');
      this._drawCornerIndex(octx, card, this.cardW - 8, this.cardH - 16, 'bottom-right');
      const rankNum = ['2','3','4','5','6','7','8','9','10'].indexOf(card.rank) + 2;
      if (rankNum >= 2 && rankNum <= 10) {
        const layout = this.PIP_LAYOUT[rankNum];
        for (const [px, py] of layout) {
          this._drawSuitPip(octx, card.suit, px * this.cardW, py * this.cardH, 0.13 * this.cardW);
        }
      } else {
        this._drawFaceCard(octx, card);
      }
    } else {
      if (!this.backPattern) {
        this.backPattern = this._buildBackPattern();
      }
      octx.fillStyle = this.backPattern;
      octx.fillRect(0, 0, this.cardW, this.cardH);
      octx.strokeStyle = '#C9A227';
      octx.lineWidth = 2.5;
      octx.strokeRect(6, 6, this.cardW - 12, this.cardH - 12);
    }
    return off.transferToImageBitmap();
  }

  _buildBackPattern() {
    const tile = new OffscreenCanvas(16, 16);
    const tctx = tile.getContext('2d');
    tctx.fillStyle = '#1A2440';
    tctx.fillRect(0, 0, 16, 16);
    tctx.fillStyle = '#2A3550';
    for (let x = 0; x < 16; x += 4) {
      for (let y = 0; y < 16; y += 4) {
        if ((x / 4 + y / 4) % 2 === 0) {
          tctx.fillRect(x, y, 2, 2);
        }
      }
    }
    return this.ctx.createPattern(tile, 'repeat');
  }

  _drawCornerIndex(ctx, card, x, y, position) {
    ctx.save();
    if (position === 'bottom-right') {
      ctx.translate(x, y);
      ctx.rotate(Math.PI);
      x = 0; y = 0;
    }
    ctx.fillStyle = this.SUIT_COLORS[card.suit];
    ctx.font = 'bold 16px JetBrains Mono';
    ctx.textAlign = position === 'bottom-right' ? 'left' : 'left';
    ctx.textBaseline = 'top';
    ctx.fillText(card.rank, x, y);
    this._drawSuitPip(ctx, card.suit, x + 6, y + 22, 8);
    ctx.restore();
  }

  _drawSuitPip(ctx, suit, cx, cy, sz) {
    ctx.save();
    ctx.translate(cx - sz/2, cy - sz/2);
    ctx.scale(sz / 48, sz / 48);
    ctx.fillStyle = this.SUIT_COLORS[suit];
    const path2d = new Path2D(this.SUIT_PATHS[suit]);
    ctx.fill(path2d);
    ctx.restore();
  }

  _drawFaceCard(ctx, card) {
    const colorMap = {'J': '#1F3A93', 'Q': '#9B7B2E', 'K': '#5B2C6F', 'A': '#0A0A0A'};
    ctx.fillStyle = '#FBF8EE';
    ctx.fillRect(20, 32, this.cardW - 40, this.cardH - 64);
    ctx.strokeStyle = colorMap[card.rank] || '#0A0A0A';
    ctx.lineWidth = 2;
    ctx.strokeRect(22, 34, this.cardW - 44, this.cardH - 68);
    ctx.fillStyle = colorMap[card.rank] || '#0A0A0A';
    ctx.font = 'bold 60px Chivo 900';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(card.rank, this.cardW / 2, this.cardH / 2);
    this._drawSuitPip(ctx, card.suit, this.cardW / 2, this.cardH / 2 + 36, 18);
  }

  drawCard(ctx, card, x, y, faceUp = true, scale = 1, rotation = 0) {
    const key = this._cacheKey(card, faceUp);
    if (!this.spriteCache.has(key)) {
      this.spriteCache.set(key, this._renderCardToOffscreen(card, faceUp));
    }
    const bitmap = this.spriteCache.get(key);
    ctx.save();
    ctx.translate(x + (this.cardW * scale) / 2, y + (this.cardH * scale) / 2);
    ctx.rotate(rotation);
    ctx.drawImage(bitmap, -(this.cardW * scale) / 2, -(this.cardH * scale) / 2, this.cardW * scale, this.cardH * scale);
    ctx.restore();
  }

  animateCardFlip(card, startX, startY, endX, endY, duration, onComplete) {
    const startTs = performance.now();
    const tick = (now) => {
      const t = Math.min(1, (now - startTs) / duration);
      const easeT = 1 - Math.pow(1 - t, 3);
      const x = startX + (endX - startX) * easeT;
      const y = startY + (endY - startY) * easeT - 60 * Math.sin(Math.PI * t);
      const flipProgress = Math.min(1, Math.max(0, (t - 0.5) * 2));
      const faceUp = flipProgress > 0.5;
      const yScale = Math.abs(Math.cos(Math.PI * flipProgress));
      this.ctx.save();
      this.ctx.translate(x + this.cardW / 2, y + this.cardH / 2);
      this.ctx.scale(1, yScale > 0.05 ? yScale : 0.05);
      this.drawCard(this.ctx, card, -this.cardW / 2, -this.cardH / 2, faceUp);
      this.ctx.restore();
      if (t < 1) { requestAnimationFrame(tick); }
      else { onComplete && onComplete(); }
    };
    requestAnimationFrame(tick);
  }

  drawChip(ctx, x, y, denomination, scale = 1) {
    const palette = CHIP_PALETTE[denomination];
    const r = 32 * scale;
    ctx.save();
    ctx.translate(x, y);
    ctx.beginPath();
    ctx.arc(0, 0, r, 0, Math.PI * 2);
    ctx.fillStyle = palette.body;
    ctx.fill();
    ctx.strokeStyle = '#0A0A0A';
    ctx.lineWidth = 1;
    ctx.stroke();
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2;
      const sx = Math.cos(angle) * r * 0.78;
      const sy = Math.sin(angle) * r * 0.78;
      ctx.fillStyle = palette.spot1;
      ctx.fillRect(sx - 6 * scale, sy - 4 * scale, 12 * scale, 8 * scale);
    }
    ctx.fillStyle = '#C9A227';
    ctx.font = `bold ${10 * scale}px Chivo 900`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(denomination.toString(), 0, 0);
    ctx.restore();
  }

  drawChipStack(ctx, x, y, chips) {
    chips.forEach((chip, idx) => {
      const offsetY = -idx * 6;
      const jitterDeg = (Math.random() - 0.5) * 4;
      ctx.save();
      ctx.translate(x, y + offsetY);
      ctx.rotate((jitterDeg * Math.PI) / 180);
      this.drawChip(ctx, 0, 0, chip.denomination, chip.scale || 1);
      ctx.restore();
    });
  }
}

const CHIP_PALETTE = {
  100:   {body: '#F2EAD3', spot1: '#B91C1C'},
  500:   {body: '#B91C1C', spot1: '#F2EAD3'},
  1000:  {body: '#0F5132', spot1: '#F2EAD3'},
  5000:  {body: '#0A0A0A', spot1: '#B91C1C'},
  10000: {body: '#5B2C6F', spot1: '#FFB800'}
};

const SUIT_SVG_PATHS = {
