def start_blackjack(db, player_id, bet_pts, perfect_pairs_pts=0, twenty_one_plus_three_pts=0):
    _atomic_deduct_points(db, player_id, bet_pts, label='blackjack_initial_bet')
    if perfect_pairs_pts > 0:
        _atomic_deduct_points(db, player_id, perfect_pairs_pts, label='blackjack_pp_sidebet')
    if twenty_one_plus_three_pts > 0:
        _atomic_deduct_points(db, player_id, twenty_one_plus_three_pts, label='blackjack_213_sidebet')
    forced_deck = redis.get(f'bonus_buy_forced_deck:{player_id}')
    if forced_deck:
        redis.delete(f'bonus_buy_forced_deck:{player_id}')
        deck = json.loads(forced_deck)
    else:
        deck = new_deck(decks=6)
        random.shuffle(deck)
    player_cards = [deck.pop(0), deck.pop(0)]
    dealer_cards = [deck.pop(0), deck.pop(0)]
    side_bets_resolved = {}
    if perfect_pairs_pts > 0:
        pp = resolve_perfect_pairs(player_cards, perfect_pairs_pts)
        side_bets_resolved['perfect_pairs'] = pp
        if pp['payout'] > 0:
            _add_points(db, player_id, pp['payout'], label=f'blackjack_pp_win')
    if twenty_one_plus_three_pts > 0:
        t = resolve_21plus3(player_cards, dealer_cards[0], twenty_one_plus_three_pts)
        side_bets_resolved['21plus3'] = t
        if t['payout'] > 0:
            _add_points(db, player_id, t['payout'], label=f'blackjack_213_win')
    animation_events = []
    for i, c in enumerate(player_cards):
        animation_events.append({'event': 'A1_BLACKJACK_CARD_DEAL', 'payload': {'card': c, 'target': 'player', 'card_index': i, 'delay_ms': i * 80}, 'sequence_id': i})
    for i, c in enumerate(dealer_cards):
        animation_events.append({'event': 'A1_BLACKJACK_CARD_DEAL', 'payload': {'card': c, 'target': 'dealer', 'card_index': i, 'face_down': i == 1, 'delay_ms': 160 + i * 80}, 'sequence_id': 2 + i})
    if side_bets_resolved.get('perfect_pairs', {}).get('payout', 0) > 0:
        animation_events.append({'event': 'A_perfect_pairs_halo', 'payload': side_bets_resolved['perfect_pairs'], 'delay_ms': 480})
