rng_to_animation_pseudocode.blackjack_dealer_reveal:
def dealer_play_sequence(db, game_id, player_id):
    game = db_query('SELECT * FROM blackjack_games WHERE id = ?', (game_id,)).fetchone()
    deck = json.loads(game['deck_json'])
    dealer_cards = json.loads(game['dealer_cards_json'])
    animation_events = [{'event': 'A5_BLACKJACK_DEALER_REVEAL', 'payload': {'hole_card': dealer_cards[1]}, 'delay_ms': 0}]
    next_delay = 320
    while hand_value(dealer_cards) < 17 or (hand_value(dealer_cards) == 17 and is_soft(dealer_cards)):
        new_card = deck.pop(0)
        if get_player_streak_mode(db, player_id) == 'cold':
            if hand_value(dealer_cards) >= 12 and hand_value(dealer_cards) <= 16 and random.random() < 0.04:
                substitute = next((c for c in deck if card_value_low(c) <= 6), None)
                if substitute:
                    deck.remove(substitute)
                    deck.insert(0, new_card)
                    new_card = substitute
                    log_streak_substitution(db, player_id, game_id, original=new_card, substituted=substitute)
        dealer_cards.append(new_card)
        animation_events.append({'event': 'A2_BLACKJACK_HIT', 'payload': {'card': new_card, 'target': 'dealer', 'new_total': hand_value(dealer_cards)}, 'delay_ms': next_delay})
        next_delay += 460
    final_total = hand_value(dealer_cards)
    if final_total == 22:
        animation_events.append({'event': 'push_22_indicator', 'payload': {}, 'delay_ms': next_delay + 200})
    return {'dealer_final_total': final_total, 'dealer_cards': dealer_cards, 'animation_events': animation_events}

rng_to_animation_pseudocode.blackjack_natural:
def detect_natural_and_emit(player_cards, dealer_cards):
    player_natural = (len(player_cards) == 2 and hand_value(player_cards) == 21)
    dealer_natural = (len(dealer_cards) == 2 and hand_value(dealer_cards) == 21)
    if player_natural and not dealer_natural:
        return {'event': 'A3_BLACKJACK_NATURAL', 'payload': {'cards': player_cards, 'payout_ratio': '6:5'}}
    if dealer_natural and not player_natural:
        return {'event': 'A5_BLACKJACK_DEALER_REVEAL', 'payload': {'reveal_natural': True}, 'follow_up': {'event': 'dealer_natural_settlement', 'delay_ms': 320}}
    if player_natural and dealer_natural:
        return {'event': 'push_natural_vs_natural', 'payload': {}}
    return None

rng_to_animation_pseudocode.blackjack_side_bet_resolve:
def resolve_perfect_pairs(player_cards, side_bet_pts):
    c1, c2 = player_cards
    if c1['rank'] != c2['rank']:
        return {'won': False, 'result': 'none', 'payout': 0}
    if c1['suit'] == c2['suit']:
        return {'won': True, 'result': 'suited', 'payout': 25 * side_bet_pts}
    same_color = (c1['suit'] in ('♥', '♦')) == (c2['suit'] in ('♥', '♦'))
    if same_color:
        return {'won': True, 'result': 'colored', 'payout': 12 * side_bet_pts}
    return {'won': True, 'result': 'mixed', 'payout': 6 * side_bet_pts}

def resolve_21plus3(player_cards, dealer_up, side_bet_pts):
    cards = list(player_cards) + [dealer_up]
    rank_values = sorted([RANK_TO_VALUE[c['rank']] for c in cards])
    suits = [c['suit'] for c in cards]
    is_flush = len(set(suits)) == 1
    is_straight = (rank_values[2] - rank_values[0] == 2 and len(set(rank_values)) == 3) or set(rank_values) == {2, 3, 14}
    is_trips = len(set(c['rank'] for c in cards)) == 1
    if is_trips and is_flush:
        return {'won': True, 'result': 'suited_trips', 'payout': 100 * side_bet_pts}
    if is_straight and is_flush:
        return {'won': True, 'result': 'straight_flush', 'payout': 40 * side_bet_pts}
    if is_trips:
        return {'won': True, 'result': 'three_of_a_kind', 'payout': 30 * side_bet_pts}
    if is_straight:
        return {'won': True, 'result': 'straight', 'payout': 10 * side_bet_pts}
    if is_flush:
        return {'won': True, 'result': 'flush', 'payout': 5 * side_bet_pts}
    return {'won': False, 'result': 'none', 'payout': 0}

rng_to_animation_pseudocode.poker_deal_multi_seat:
def poker_deal(db, session_id):
    session = db_query('SELECT * FROM poker_sessions WHERE id = ?', (session_id,)).fetchone()
    seats = db_query('SELECT * FROM poker_seats WHERE session_id = ? AND active = 1 ORDER BY seat_number', (session_id,)).fetchall()
    if len(seats) < 2:
        raise InvalidState('need_at_least_2_seats')
    presets = json.loads(session['preset_hands_json'] or '{}')
    deck = new_deck(decks=1)
    random.shuffle(deck)
    used_in_presets = []
    for seat_id, holes in presets.items():
        used_in_presets.extend(holes)
    for c in used_in_presets:
        deck = [d for d in deck if not (d['rank'] == c['rank'] and d['suit'] == c['suit'])]
    animation_events = []
    delay = 0
    for round_n in range(2):
        for s_idx, seat in enumerate(seats):
            sid_str = str(seat['id'])
            if sid_str in presets:
                card = presets[sid_str][round_n]
            else:
                card = deck.pop(0)
            existing = json.loads(seat['hole_cards_json'] or '[]')
            existing.append(card)
            db_execute('UPDATE poker_seats SET hole_cards_json = ? WHERE id = ?', (json.dumps(existing), seat['id']))
            animation_events.append({'event': 'A6_POKER_DEAL_MULTI_SEAT', 'payload': {'seat_id': seat['id'], 'card': card, 'card_index': round_n, 'face_down': True}, 'delay_ms': delay})
            delay += 120
    db_execute('UPDATE poker_sessions SET deck_json = ?, stage = ? WHERE id = ?', (json.dumps(deck), 'preflop', session_id))
    return {'animation_events': animation_events}

