def poker_advance_flop(db, session_id):
    session = db_query('SELECT * FROM poker_sessions WHERE id = ?', (session_id,)).fetchone()
    if session['stage'] != 'preflop':
        raise InvalidState('flop_can_only_advance_from_preflop')
    deck = json.loads(session['deck_json'])
    burn = deck.pop(0)
    flop = [deck.pop(0), deck.pop(0), deck.pop(0)]
    db_execute('UPDATE poker_sessions SET community_cards_json = ?, deck_json = ?, stage = ? WHERE id = ?', (json.dumps(flop), json.dumps(deck), 'flop', session_id))
